import { ScoringRuleType } from "@api";
import { Countdown } from "@components/countdown";
import { CategoryIcon } from "@icons/category-icons";
import { Medal } from "@icons/medal";
import { canBeFinished, ScoreObjective } from "@mytypes/score";
import { GlobalStateContext } from "@utils/context-provider";
import { Score } from "@components/score";
import { getPotentialPoints, getTotalPoints } from "@utils/utils";
import { useContext } from "react";
import { twMerge } from "tailwind-merge";

type UniqueCategoryCardProps = {
  objective: ScoreObjective;
  selected: boolean;
  teamId?: number;
  onClick: () => void;
};

function isRepeatable(objective: ScoreObjective): boolean {
  return objective.scoring_rules.some(
    (preset) => preset.scoring_rule === ScoringRuleType.POINTS_BY_VALUE,
  );
}

function getSubmissionCap(objective: ScoreObjective): number {
  const preset = objective.scoring_rules.find(
    (preset) => preset.scoring_rule === ScoringRuleType.POINTS_BY_VALUE,
  );
  if (!preset) {
    return 0;
  }
  let numItems = 0;
  let remainingPointBudget = preset.point_cap || 0;
  let pointIndex = 0;
  while (remainingPointBudget >= 0) {
    const points =
      pointIndex < preset.points.length
        ? preset.points[pointIndex]
        : preset.points[preset.points.length - 1];
    remainingPointBudget -= points;
    numItems++;
    pointIndex++;
  }
  return numItems - 1; // Subtract 1 because the loop runs one extra time after exceeding the budget
}

export const UniqueCategoryCard = ({
  objective,
  selected,
  teamId = 0,
  onClick,
  ...props
}: UniqueCategoryCardProps & React.HTMLAttributes<HTMLDivElement>) => {
  const { currentEvent } = useContext(GlobalStateContext);
  const totalItems = objective.children.length;
  const totalVariants = objective.children.reduce(
    (acc, variantCategory) => acc + variantCategory.children.length,
    0,
  );
  const multiUnique = objective.children.find(isRepeatable);
  const multiUniqueCap = multiUnique ? getSubmissionCap(multiUnique) : 0;
  if (objective.team_score[teamId] === undefined) {
    return null;
  }
  const multiUniqueCurrentNum = multiUnique?.team_score[teamId].number() || 0;
  const numItems = objective.children.reduce((acc, subCategory) => {
    if (subCategory.team_score[teamId].number() > 0) {
      return acc + 1;
    }
    return acc;
  }, 0);
  const numVariants = teamId
    ? objective.children.reduce((acc, subCategory) => {
        return (
          acc +
          subCategory.children.reduce((numVariants, child) => {
            if (child.team_score[teamId].number() > 0) {
              return numVariants + 1;
            }
            return numVariants;
          }, 0)
        );
      }, 0)
    : 0;

  const finishable = canBeFinished(objective);
  return (
    <div className="h-full">
      <div
        {...props}
        className={twMerge(
          "card h-full cursor-pointer bborder shadow-xl transition-all duration-150",
          selected
            ? "bg-card-highlight text-highlight-content ring-3 ring-primary"
            : "bg-card hover:bg-card-highlight hover:border-2 hover:border-primary hover:text-highlight-content",
          props?.className,
        )}
        key={`unique-card-${objective.id}`}
        onClick={onClick}
      >
        <div
          className={twMerge(
            "m-0 card-title flex items-center justify-center rounded-t-box bborder-b bg-base-300/50 p-2 sm:grid sm:grid-cols-[1fr_3fr_1fr]",
            selected ? "border-0" : "",
          )}
        >
          <div className="hidden items-center sm:flex">
            <CategoryIcon name={objective.name} objective={objective} />
          </div>
          <div className="text-center">
            <h1 className="font-extrabold">{objective.name}</h1>
            <h1 className="font-bold text-info">{objective.extra}</h1>
          </div>
          <div className="hidden justify-end sm:flex">
            <Medal rank={objective.team_score[teamId].rank()} size={28} />
          </div>
        </div>
        <div className="relative flex h-full min-h-2 flex-col justify-between px-4">
          <div className="absolute top-2 right-2 text-xs text-base-content/80">
            <Score
              actualNumberOfPoints={getTotalPoints(objective)[teamId]}
              potentialNumberOfPoints={getPotentialPoints(objective)[teamId]}
              usesMedals={currentEvent?.uses_medals}
            />
          </div>
          <div className="flex h-full flex-col items-center justify-center gap-1 pt-5 pb-2">
            <div
              className={twMerge(
                "text-xl font-extrabold whitespace-nowrap sm:text-4xl",
                numItems === totalItems ? "text-success" : "text-warning",
                !finishable && "text-base-content",
              )}
            >
              {finishable ? `${numItems} / ${totalItems}` : numItems}
            </div>
            {!!totalVariants && (
              <div
                className={twMerge(
                  "text-lg",
                  numVariants === totalVariants
                    ? "text-success"
                    : "text-base-content/70",
                )}
              >
                {`Variants: ${numVariants} / ${totalVariants}`}
              </div>
            )}
            {multiUnique && (
              <div
                className={twMerge(
                  "text-lg",
                  multiUniqueCurrentNum >= multiUniqueCap
                    ? "text-success"
                    : "text-base-content/70",
                )}
              >
                {`Repeatable: ${multiUniqueCurrentNum} / ${multiUniqueCap}`}
              </div>
            )}
          </div>
          {finishable && (
            <progress
              className={twMerge(
                "progress my-2 select-none",
                numItems === totalItems ? "progress-success" : "progress-error",
              )}
              value={numItems / totalItems}
              max="1"
            ></progress>
          )}
        </div>
        {objective.valid_to && new Date(objective.valid_to) > new Date() && (
          <div className="flex h-16 items-center justify-center gap-2 p-2">
            <span> Valid until:</span>
            <Countdown
              target={new Date(objective.valid_to || "")}
              size="small"
            />
          </div>
        )}
        {objective.valid_to && new Date(objective.valid_to) < new Date() && (
          <div className="flex h-16 items-center justify-center gap-4">
            <span> Locked</span>
          </div>
        )}
      </div>
    </div>
  );
};
