import { useEffect } from "react";
import {
  CountingMethod,
  TrackedValue,
  Objective,
  ObjectiveCreate,
  ObjectiveType,
  Event,
} from "@api";
import { Dialog } from "@components/dialog";
import { setFormValues, useAppForm } from "@components/form/context";
import { useQueryClient } from "@tanstack/react-query";
import { useCreateObjective, useGetScoringRulesForEvent } from "@api";
import { Link } from "@tanstack/react-router";

interface CategoryFormModalProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  event: Event;
  parentId: number;
  existingCategory?: Objective | null;
}

export function CategoryFormModal({
  isOpen,
  setIsOpen,
  event,
  parentId,
  existingCategory,
}: CategoryFormModalProps) {
  const qc = useQueryClient();
  const { scoringRules } = useGetScoringRulesForEvent(event.id);

  const form = useAppForm({
    defaultValues: {
      counting_method: null,
      name: "",
      extra: "",
      tracked_value: TrackedValue.COMPLETED_CHILD_OBJECTIVE_COUNT,
      tracked_value_explanation: null,
      required_number: 1,
      conditions: [],
      parent_id: parentId,
      objective_type: ObjectiveType.CATEGORY,
      scoring_rule_ids: [],
    } as unknown as ObjectiveCreate,
    onSubmit: (data) => createObjective(data.value),
  });

  const { createObjective } = useCreateObjective(qc, event.id, () => {
    setIsOpen(false);
    form.reset();
  });

  useEffect(() => {
    if (!isOpen) return;
    form.reset();
    if (existingCategory) {
      setFormValues(form, existingCategory);
      form.setFieldValue(
        "scoring_rule_ids",
        existingCategory.scoring_rules.map((r) => r.id),
      );
    }
  }, [isOpen, existingCategory]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <Dialog
      title={existingCategory ? "Edit Category" : "Create Category"}
      open={isOpen}
      setOpen={setIsOpen}
      className="max-w-lg"
    >
      <form
        className="flex w-full flex-col gap-2 rounded-box bg-base-300 p-4"
        onSubmit={(e) => {
          e.preventDefault();
          form.handleSubmit();
        }}
      >
        <div className="rounded-box border border-info/20 bg-info/10 p-3 text-left text-sm">
          Need category examples?{" "}
          <Link
            to="/admin/events/$eventId/objective-help"
            params={{ eventId: event.id }}
            className="link link-primary"
          >
            Open the objective help page
          </Link>
          .
        </div>
        <form.AppField
          name="name"
          children={(field) => (
            <field.TextField label="Objective name" required />
          )}
        />
        <form.AppField
          name="extra"
          children={(field) => <field.TextField label="Extra" />}
        />
        <form.AppField
          name="counting_method"
          children={(field) => (
            <field.SelectField
              label="How it counts"
              options={Object.values(CountingMethod)}
              required
            />
          )}
        />
        <form.AppField
          name="scoring_rule_ids"
          children={(field) => (
            <field.MultiSelectField
              label="How it gives points"
              options={scoringRules.map((rule) => ({
                label: rule.name,
                value: rule.id,
              }))}
            />
          )}
        />
        <div className="mt-4 flex flex-row justify-end gap-2">
          <button
            type="button"
            className="btn btn-error"
            onClick={() => setIsOpen(false)}
          >
            Cancel
          </button>
          <button type="submit" className="btn btn-primary">
            Save
          </button>
        </div>
      </form>
    </Dialog>
  );
}
