export function useGetUser() {
  const query = useGetUserBase({
    query: {
      enabled: () => isLoggedIn(),
      refetchOnMount: false,
      select: (user) => {
        if (new Date(user.token_expiry_timestamp || 0) < new Date()) {
          localStorage.removeItem("auth");
          return null;
        }
        return user;
      },
    },
  });
  return { ...query, user: query.data };
}

