export function useDuplicateObjective(qc: QueryClient, eventId: number) {
  const m = useMutation({
    mutationFn: async (objective: Objective) =>
      duplicateObjective(objective, eventId, objective.parent_id),
    onSuccess: () =>
      qc.invalidateQueries({
        queryKey: getGetObjectiveTreeForEventBaseQueryKey(eventId),
      }),
  });
  return {
    duplicateObjective: m.mutate,
    duplicateObjectivePending: m.isPending,
  };
}

async function duplicateObjective(
  objective: Objective,
  eventId: number,
  parentId: number,
): Promise<Objective> {
  const dupe = JSON.parse(JSON.stringify(objective)) as ObjectiveCreate;
  dupe.id = undefined;
  dupe.parent_id = parentId;
  dupe.scoring_rule_ids = objective.scoring_rules.map((rule) => rule.id);
  const newObjective = await createObjectiveBase(eventId, dupe);
  if (objective.children.length > 0) {
    const children = await Promise.all(
      objective.children.map((child) =>
        duplicateObjective(child, eventId, newObjective.id),
      ),
    );
    newObjective.children = children;
  }
  return newObjective;
}

export function useCreateBulkObjectives(
  qc: QueryClient,
  eventId: number,
  categoryId: number,
  callback?: () => void,
) {
  const m = useMutation({
    mutationFn: (bulkObjective: BulkObjectiveCreate) => {
      const objectives: ObjectiveCreate[] = bulkObjective.nameList
        .split(",")
        .map((name) => ({
          name: name.trim(),
          required_number: 1,
          objective_type: ObjectiveType.ITEM,
          counting_method: bulkObjective.counting_method,
          tracked_value: TrackedValue.STACK_SIZE,
          scoring_rule_ids: bulkObjective.scoring_rule_ids,
          parent_id: categoryId,
          conditions: [
            {
              field: bulkObjective.item_field,
              operator: Operator.EQ,
              value: name,
            },
          ],
        }));
      return Promise.all(
        objectives.map((obj) => createObjectiveBase(eventId, obj)),
      );
    },
    onSuccess: () => {
      qc.invalidateQueries({
        queryKey: getGetObjectiveTreeForEventBaseQueryKey(eventId),
      });
      callback?.();
    },
  });
  return {
    createBulkObjectives: m.mutate,
    createBulkObjectivesPending: m.isPending,
  };
}

export function useChangeCategoryReleaseDates(
  qc: QueryClient,
  eventId: number,
) {
  const m = useMutation({
    mutationFn: ({
      objective,
      start,
      end,
    }: {
      objective: Objective;
      start: Date | null;
      end: Date | null;
    }) => {
      const promises = (flatMap(objective) as Objective[]).map((child) =>
        createObjectiveBase(eventId, toObjectiveCreate(child, start, end)),
      );
      return Promise.all(promises);
    },
    onSuccess: () => {
      qc.invalidateQueries({
        queryKey: getGetObjectiveTreeForEventBaseQueryKey(eventId),
      });
    },
  });
  return {
    changeCategoryReleaseDates: m.mutate,
    changeCategoryReleaseDatesPending: m.isPending,
  };
}

