// --- Utility ---

export function useFile<T>(filePath: string, format: "text" | "json" = "json") {
  return useQuery({
    queryKey: [filePath],
    queryFn: async () =>
      fetch(filePath).then((res) => {
        if (format === "json") return res.json() as Promise<T>;
        return res.text() as Promise<T>;
      }),
    refetchOnMount: false,
  });
}

// --- Helpers ---

function toObjectiveCreate(
  objective: Objective,
  start: Date | null,
  end: Date | null,
): ObjectiveCreate {
  return {
    ...objective,
    valid_from: start ?? undefined,
    valid_to: end ?? undefined,
    scoring_rule_ids: objective.scoring_rules?.map((rule) => rule.id) ?? [],
  };
}

